interface Window {
  CMS: Proxy;
  CMS_MANUAL_INIT?: boolean;
  initCMS: Function;
  showDirectoryPicker: Function;
  // React stuff exposed on `window`. See `main.js`
  createClass: Function;
  createElement: Function;
  h: Function;
  rf: any;
  html: Function;
  // Markdown parser and HTML sanitizer exposed on `window`. See `main.js`
  marked: any;
  DOMPurify: any;
}

interface Navigator {
  userAgentData?: { platform: string; brands: { brand: string }[] };
}

interface Document {
  startViewTransition?: Function;
}

interface Element {
  scrollIntoViewIfNeeded?: Function;
}

interface FileSystemFileHandle {
  move?: Function;
  createWritable?: Function;
}

interface FileSystemDirectoryHandle {
  keys: Function;
  entries: Function;
  requestPermission: Function;
}

/**
 * Silence some import errors.
 * @see https://stackoverflow.com/q/70682803
 */
declare module '*.svelte' {
  const content: any;
  export default content;
}

declare module '*.svg?raw&inline' {
  const content: string;
  export default content;
}

/**
 * YAML files are transformed into JS object modules by the `yamlToJS` Vite plugin.
 */
declare module '*.yaml' {
  const content: Record<string, any>;
  export default content;
}

/**
 * The CMS configuration schema, bundled with the app by the `bundleSchema` Vite plugin. It’s `null`
 * when the dev server starts without a schema generated by an earlier build.
 */
declare module 'virtual:config-schema' {
  const content: Record<string, any> | null;
  export default content;
}

/**
 * The version and the dependency ranges of the app, taken from `package.json` by the
 * `bundlePackageInfo` Vite plugin.
 */
declare module 'virtual:package-info' {
  export const version: string;
  export const dependencies: Record<string, string>;
}

/**
 * The vendor and experimental media types the app needs beyond the standard ones, picked from the
 * full table of the `mime` package by the `bundleMimeTypes` Vite plugin.
 */
declare module 'virtual:mime-other-types' {
  const types: Record<string, string[]>;
  export default types;
}

/**
 * The modules the backend chunks import from the main bundle, as an array of modules, each an array
 * of exports, collected by the `collectSharedModules` Vite plugin, along with the global property
 * to share them on. Empty outside the CDN builds, where the chunks are part of the same module
 * graph.
 */
declare module 'virtual:shared-modules' {
  const modules: unknown[][];
  export const sharedModulesKey: string;
  export default modules;
}
